public class SwitchPattern { static String f(Object x) { return switch(x) {case null -> "nil"; case String s when s.length()>1 -> "long:"+s; case String s -> "short:"+s; case Integer i -> "int:"+i; default -> "other";};} public static void main(String[] a) {System.out.println(f(null));System.out.println(f("ab"));System.out.println(f("a"));System.out.println(f(2));System.out.println(f(2L));} }